CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, cash_balance DECIMAL(15,2) NOT NULL DEFAULT 100000.00, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, ticker VARCHAR(10) NOT NULL, action VARCHAR(10) NOT NULL, shares DECIMAL(15,4) NOT NULL, price DECIMAL(15,2) NOT NULL, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS holdings (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, ticker VARCHAR(10) NOT NULL, shares DECIMAL(15,4) NOT NULL DEFAULT 0, average_price DECIMAL(15,2) NOT NULL DEFAULT 0, UNIQUE KEY user_ticker (user_id,ticker), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
